-- Épreuves d'admission 2026 (QCM proposés par Dylan Charré, dossier Drive « Proposition test et entretien d'admission Cyber 2026 »).
-- À exécuter une fois, après schema.sql, quand au moins un compte admin existe : les trois épreuves sont créées NON publiées,
-- sur invitation, 1 minute et 1 point par question (tout ou rien sur les questions à plusieurs réponses).
-- Les explications de chaque réponse sont dans supabase/seed/admission-2026/*.json (pour la correction et le debrief).
do $seed$
declare v_owner uuid; v_test uuid; v_q uuid;
begin
  select id into v_owner from profiles where role = 'admin' order by created_at limit 1;
  if v_owner is null then raise exception 'Créez d''abord un compte admin'; end if;
    values (v_owner, $q$Admission Bachelor 1 Cybersécurité 2026$q$, $q$QCM d'admission B1 Cyber (proposition de Dylan, v2, relue). 55 questions dont 5 énigmes CYBEROKU, 55 minutes, 1 point par question ; questions à plusieurs réponses : tout ou rien. Aucun prérequis technique : logique, raisonnement pas à pas et bons réflexes numériques. Seuil d'admissibilité proposé : 28/55 (50 %).$q$, 55, false, true, true, true, 3) returning id into v_test;
x ← 4
y ← x × 2
x ← y + 1
Afficher x$q$, $q$[{"id": "a", "text": "8"}, {"id": "b", "text": "9"}, {"id": "c", "text": "4"}, {"id": "d", "text": "5"}]$q$::jsonb, 1) returning id into v_q;
total ← 0
Pour i allant de 1 à 4 :
    total ← total + i
Afficher total$q$, $q$[{"id": "a", "text": "9"}, {"id": "b", "text": "4"}, {"id": "c", "text": "5"}, {"id": "d", "text": "10"}]$q$::jsonb, 1) returning id into v_q;
prix ← 20
Si prix > 15 alors
    prix ← prix - 5
Afficher prix$q$, $q$[{"id": "a", "text": "5"}, {"id": "b", "text": "20"}, {"id": "c", "text": "15"}, {"id": "d", "text": "25"}]$q$::jsonb, 1) returning id into v_q;
âge ← 17
Si âge ≥ 18 alors
    Afficher "majeur"
Sinon
    Afficher "mineur"$q$, $q$[{"id": "a", "text": "Rien"}, {"id": "b", "text": "majeur"}, {"id": "c", "text": "mineur"}, {"id": "d", "text": "majeur puis mineur"}]$q$::jsonb, 1) returning id into v_q;
mot = "cyber"
print(len(mot))$q$, $q$[{"id": "a", "text": "cyber"}, {"id": "b", "text": "5"}, {"id": "c", "text": "4"}, {"id": "d", "text": "1"}]$q$::jsonb, 1) returning id into v_q;
a ← 3
b ← a + 2
Afficher a + b$q$, $q$[{"id": "a", "text": "32"}, {"id": "b", "text": "8"}, {"id": "c", "text": "5"}, {"id": "d", "text": "3"}]$q$::jsonb, 1) returning id into v_q;
mdp = "soleil"
if len(mdp) >= 8:
    print("accepté")
else:
    print("trop court")$q$, $q$[{"id": "a", "text": "accepté puis trop court"}, {"id": "b", "text": "trop court"}, {"id": "c", "text": "Une erreur"}, {"id": "d", "text": "accepté"}]$q$::jsonb, 1) returning id into v_q;
nom = "Alice"
print("Bonjour " + nom)$q$, $q$[{"id": "a", "text": "Bonjour nom"}, {"id": "b", "text": "Une erreur"}, {"id": "c", "text": "nom Alice"}, {"id": "d", "text": "Bonjour Alice"}]$q$::jsonb, 1) returning id into v_q;
1 . 3 4
. 4 . 2
2 ? 4 .
4 3 . 1
Quel chiffre remplace le « ? » ?$q$, $q$[{"id": "a", "text": "1"}, {"id": "b", "text": "2"}, {"id": "c", "text": "3"}, {"id": "d", "text": "4"}]$q$::jsonb, 1) returning id into v_q;
# @ $
@ $ #
$ ? @
Quel symbole remplace le « ? » ?$q$, $q$[{"id": "a", "text": "#"}, {"id": "b", "text": "@"}, {"id": "c", "text": "$"}, {"id": "d", "text": "On ne peut pas savoir"}]$q$::jsonb, 1) returning id into v_q;
Pare-feu activé
Accès refusé
Session ouverte
Sauvegarde terminée
Quel est le mot caché ?$q$, $q$[{"id": "a", "text": "PASS"}, {"id": "b", "text": "PAOS"}, {"id": "c", "text": "SAPS"}, {"id": "d", "text": "PARS"}]$q$::jsonb, 1) returning id into v_q;
    values (v_owner, $q$Admission Bachelor 3 Cybersécurité 2026$q$, $q$QCM d'admission B3 Cyber (proposition de Dylan, v4, relue). 50 minutes, 1 point par question ; questions à plusieurs réponses : tout ou rien. Niveau visé : sortie de BTS SIO SISR ou BTS CIEL IR. Seuil d'admissibilité proposé : 25/50.$q$, 50, false, true, true, true, 3) returning id into v_test;
for i in 1 2 3; do
    echo "Serveur$i"
done$q$, $q$[{"id": "a", "text": "Serveur$i, trois fois, sur trois lignes"}, {"id": "b", "text": "Serveur1, Serveur2 et Serveur3, sur trois lignes"}, {"id": "c", "text": "Une erreur de syntaxe à cause des guillemets"}, {"id": "d", "text": "Serveur123, sur une seule ligne"}]$q$::jsonb, 1) returning id into v_q;
x = 5
if x > 3:
    print("A")
elif x > 1:
    print("B")
else:
    print("C")$q$, $q$[{"id": "a", "text": "C"}, {"id": "b", "text": "A puis B"}, {"id": "c", "text": "B"}, {"id": "d", "text": "A"}]$q$::jsonb, 1) returning id into v_q;
serveurs = ["web", "dns", "mail"]
print(len(serveurs), serveurs[1])$q$, $q$[{"id": "a", "text": "3 web"}, {"id": "b", "text": "3 mail"}, {"id": "c", "text": "3 dns"}, {"id": "d", "text": "2 dns"}]$q$::jsonb, 1) returning id into v_q;
Get-ADUser -Filter * | Where-Object { $_.Enabled -eq $false }$q$, $q$[{"id": "a", "text": "Elle liste les comptes Active Directory actifs"}, {"id": "b", "text": "Elle désactive tous les comptes Active Directory"}, {"id": "c", "text": "Elle supprime les comptes désactivés"}, {"id": "d", "text": "Elle liste les comptes Active Directory désactivés"}]$q$::jsonb, 1) returning id into v_q;
grep "Failed password" /var/log/auth.log | wc -l$q$, $q$[{"id": "a", "text": "Elle compte le nombre d'utilisateurs ayant un compte sur le système"}, {"id": "b", "text": "Elle affiche les mots de passe saisis par erreur lors des connexions"}, {"id": "c", "text": "Elle supprime du journal les lignes des connexions échouées"}, {"id": "d", "text": "Elle compte les lignes du journal contenant « Failed password » (échecs de connexion)"}]$q$::jsonb, 1) returning id into v_q;
tentatives = 0
while tentatives < 3:
    tentatives += 1
print(tentatives)$q$, $q$[{"id": "a", "text": "3"}, {"id": "b", "text": "2"}, {"id": "c", "text": "Rien : la boucle est infinie"}, {"id": "d", "text": "4"}]$q$::jsonb, 1) returning id into v_q;
if [ -f /etc/backup.conf ]; then
    echo "OK"
fi$q$, $q$[{"id": "a", "text": "Il crée le fichier /etc/backup.conf"}, {"id": "b", "text": "Il affiche OK si le fichier /etc/backup.conf existe"}, {"id": "c", "text": "Il supprime le fichier /etc/backup.conf"}, {"id": "d", "text": "Il affiche le contenu du fichier /etc/backup.conf"}]$q$::jsonb, 1) returning id into v_q;
ports = [22, 80, 443]
for p in ports:
    if p != 80:
        print(p)$q$, $q$[{"id": "a", "text": "Rien"}, {"id": "b", "text": "80"}, {"id": "c", "text": "22 et 443"}, {"id": "d", "text": "22, 80 et 443"}]$q$::jsonb, 1) returning id into v_q;
    values (v_owner, $q$Admission Mastère Cybersécurité (M1) 2026$q$, $q$QCM d'admission Mastère Cyber, entrée M1 (proposition de Dylan, v2, relue). 50 minutes, 1 point par question ; questions à plusieurs réponses : tout ou rien. Niveau visé : sortie de Bac+3 (Licence ou BUT informatique, TP AIS, Bachelor cyber). Seuil d'admissibilité proposé : 25/50.$q$, 50, false, true, true, true, 3) returning id into v_test;
10.0.0.0/8 via R1
10.1.0.0/16 via R2
10.1.2.0/24 via R3
0.0.0.0/0 via R4
Par où part un paquet à destination de 10.1.2.45 ?$q$, $q$[{"id": "a", "text": "R2"}, {"id": "b", "text": "R1"}, {"id": "c", "text": "R4"}, {"id": "d", "text": "R3"}]$q$::jsonb, 1) returning id into v_q;
ports = {"ssh": 22, "http": 80}
ports["https"] = 443
print(len(ports), ports.get("ftp", 21))$q$, $q$[{"id": "a", "text": "3 21"}, {"id": "b", "text": "Une erreur KeyError"}, {"id": "c", "text": "3 None"}, {"id": "d", "text": "2 21"}]$q$::jsonb, 1) returning id into v_q;
ip = "192.168.1.25"
octets = ip.split(".")
print(octets[-1], len(octets))$q$, $q$[{"id": "a", "text": "25 4"}, {"id": "b", "text": "192 4"}, {"id": "c", "text": "1 4"}, {"id": "d", "text": "25 3"}]$q$::jsonb, 1) returning id into v_q;
logs = ["OK", "FAIL", "OK", "FAIL", "FAIL"]
echecs = [l for l in logs if l == "FAIL"]
print(len(echecs))$q$, $q$[{"id": "a", "text": "2"}, {"id": "b", "text": "[\"FAIL\", \"FAIL\", \"FAIL\"]"}, {"id": "c", "text": "3"}, {"id": "d", "text": "5"}]$q$::jsonb, 1) returning id into v_q;
try:
    x = int("abc")
    print("A")
except ValueError:
    print("B")
finally:
    print("C")$q$, $q$[{"id": "a", "text": "C"}, {"id": "b", "text": "B puis C"}, {"id": "c", "text": "B"}, {"id": "d", "text": "A puis C"}]$q$::jsonb, 1) returning id into v_q;
cut -d: -f1 /etc/passwd | sort | head -3$q$, $q$[{"id": "a", "text": "Elle affiche les 3 premiers noms de comptes du système, par ordre alphabétique"}, {"id": "b", "text": "Elle supprime les 3 premiers comptes"}, {"id": "c", "text": "Elle affiche les 3 premières lignes complètes de /etc/passwd"}, {"id": "d", "text": "Elle affiche les 3 premiers mots de passe"}]$q$::jsonb, 1) returning id into v_q;
^[0-9]{1,3}(\.[0-9]{1,3}){3}$
Laquelle de ces chaînes n'est PAS reconnue ?$q$, $q$[{"id": "a", "text": "999.999.999.999"}, {"id": "b", "text": "192.168.1.1"}, {"id": "c", "text": "192.168.1"}, {"id": "d", "text": "10.0.0.255"}]$q$::jsonb, 1) returning id into v_q;
subprocess.run("ping -c 1 " + host, shell=True)$q$, $q$[{"id": "a", "text": "Aucun, car la commande ping ne modifie rien sur le système"}, {"id": "b", "text": "Il permet une injection de commandes (par exemple host = \"8.8.8.8; rm -rf ~\")"}, {"id": "c", "text": "Il est vulnérable au XSS si le résultat est affiché dans une page"}, {"id": "d", "text": "Il provoque un dépassement de tampon si host est trop long"}]$q$::jsonb, 1) returning id into v_q;
char buf[8];
strcpy(buf, entree_utilisateur);$q$, $q$[{"id": "a", "text": "Une fuite mémoire"}, {"id": "b", "text": "Un dépassement de tampon si l'entrée dépasse 7 caractères"}, {"id": "c", "text": "Une injection SQL"}, {"id": "d", "text": "Aucun, strcpy vérifie la taille de la destination"}]$q$::jsonb, 1) returning id into v_q;
