Laquelle corrigez-vous en premier ?$q$, $q$[{"id": "a", "text": "Les trois en même temps, dans l'ordre des scores"}, {"id": "b", "text": "La n° 2"}, {"id": "c", "text": "La n° 1"}, {"id": "d", "text": "La n° 3"}]$q$::jsonb, 1) returning id into v_q;
end
$seed$;
