  insert into answer_keys(question_id, correct) values (v_q, '["d"]'::jsonb);
  insert into questions(test_id, position, type, prompt, options, points) values (v_test, 42, 'mcq_single', $q$Un poste ne parvient pas à joindre sa passerelle, alors que les autres postes branchés sur le même switch fonctionnent. Où cherchez-vous en priorité ?$q$, $q$[{"id": "a", "text": "Sur le pare-feu Internet, qui filtre peut-être le trafic de ce poste"}, {"id": "b", "text": "Sur le serveur DNS, qui ne résout peut-être plus l'adresse de la passerelle"}, {"id": "c", "text": "Sur le poste lui-même : câble, port du switch, configuration IP, VLAN du port"}, {"id": "d", "text": "Chez le fournisseur d'accès à Internet, qui coupe peut-être ce poste"}]$q$::jsonb, 1) returning id into v_q;
