  insert into questions(test_id, position, type, prompt, options, points) values (v_test, 47, 'mcq_single', $q$Une connexion SSH vers un serveur échoue avec le message « Connection refused ». Que peut-on en déduire ?$q$, $q$[{"id": "a", "text": "Le serveur est joignable, mais aucun service n'écoute sur ce port ou un pare-feu rejette la connexion"}, {"id": "b", "text": "Le serveur n'existe pas ou est éteint"}, {"id": "c", "text": "Le mot de passe ou la clé SSH sont incorrects"}, {"id": "d", "text": "Le nom du serveur n'est pas résolu par le DNS"}]$q$::jsonb, 1) returning id into v_q;
