  insert into questions(test_id, position, type, prompt, options, points) values (v_test, 49, 'mcq_single', $q$Les utilisateurs signalent que le serveur de fichiers est très lent tous les jours entre 12 h et 13 h, et seulement sur ce créneau. Quelle hypothèse vérifiez-vous en premier ?$q$, $q$[{"id": "a", "text": "Une sauvegarde ou une tâche planifiée qui s'exécute sur ce créneau"}, {"id": "b", "text": "Une infection par un virus qui se déclenche sur le serveur"}, {"id": "c", "text": "Une panne intermittente du serveur DNS de l'entreprise"}, {"id": "d", "text": "Un câble réseau défectueux entre le serveur et le switch"}]$q$::jsonb, 1) returning id into v_q;
